{
  "name": "@morphllm/opencode-morph-plugin",
  "version": "2.0.17",
  "description": "OpenCode plugin for Morph SDK - fast apply, WarpGrep codebase search",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "instructions/"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "bun test",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "ci": "bun test && bun run build && bun run typecheck"
  },
  "dependencies": {
    "@morphllm/morphsdk": "0.2.173",
    "@opencode-ai/plugin": "1.18.29",
    "@opencode-ai/sdk": "^1.18.29"
  },
  "devDependencies": {
    "bun-types": "latest",
    "typescript": "^5.0.0"
  },
  "keywords": [
    "opencode",
    "plugin",
    "morph",
    "fast-apply",
    "warpgrep",
    "code-search",
    "code-editing"
  ],
  "author": "Morph",
  "repository": {
    "type": "git",
    "url": "https://github.com/morphllm/opencode-morph-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/morphllm/opencode-morph-plugin/issues"
  },
  "homepage": "https://github.com/morphllm/opencode-morph-plugin#readme",
  "license": "MIT"
}
